/// Adds a route for every contract component `kernel` implements to `routes`, each answered by `service` after the checks the specification states for it.
pub fn kernel_routes<A, S, H>(
    routes: strata_runtime::Routes<A>,
    service: std::sync::Arc<S>,
    hooks: std::sync::Arc<H>,
) -> strata_runtime::Routes<A>
where
    A: strata_runtime::Authorizer,
    S: crate::contracts::Kernel + Send + Sync + 'static,
    H: KernelHooks,
{
    routes
        .serve_checked::<
            DecideIntent,
            _,
            _,
        >({
            let (service, hooks) = (service.clone(), hooks.clone());
            move |
                caller: strata_runtime::Caller,
                request: crate::contracts::DecideIntentRequest|
            {
                let (service, hooks) = (service.clone(), hooks.clone());
                async move {
                    serve_decide_intent(&*service, &*hooks, caller, request).await
                }
            }
        })
        .serve_checked::<
            PlanIntentNeeds,
            _,
            _,
        >({
            let (service, hooks) = (service.clone(), hooks.clone());
            move |
                caller: strata_runtime::Caller,
                request: crate::contracts::PlanIntentNeedsRequest|
            {
                let (service, hooks) = (service.clone(), hooks.clone());
                async move {
                    serve_plan_intent_needs(&*service, &*hooks, caller, request).await
                }
            }
        })
        .serve_checked::<
            AnswerRead,
            _,
            _,
        >({
            let (service, hooks) = (service.clone(), hooks.clone());
            move |
                caller: strata_runtime::Caller,
                request: crate::contracts::AnswerReadRequest|
            {
                let (service, hooks) = (service.clone(), hooks.clone());
                async move {
                    serve_answer_read(&*service, &*hooks, caller, request).await
                }
            }
        })
        .serve_checked::<
            PlanReadNeeds,
            _,
            _,
        >({
            let (service, hooks) = (service.clone(), hooks.clone());
            move |
                caller: strata_runtime::Caller,
                request: crate::contracts::PlanReadNeedsRequest|
            {
                let (service, hooks) = (service.clone(), hooks.clone());
                async move {
                    serve_plan_read_needs(&*service, &*hooks, caller, request).await
                }
            }
        })
        .serve_checked::<
            CheckRecordVisibility,
            _,
            _,
        >({
            let (service, hooks) = (service.clone(), hooks.clone());
            move |
                caller: strata_runtime::Caller,
                request: crate::contracts::CheckRecordVisibilityRequest|
            {
                let (service, hooks) = (service.clone(), hooks.clone());
                async move {
                    serve_check_record_visibility(&*service, &*hooks, caller, request)
                        .await
                }
            }
        })
        .serve_checked::<
            ApplyStateDelta,
            _,
            _,
        >({
            let (service, hooks) = (service.clone(), hooks.clone());
            move |
                caller: strata_runtime::Caller,
                request: crate::contracts::ApplyStateDeltaRequest|
            {
                let (service, hooks) = (service.clone(), hooks.clone());
                async move {
                    serve_apply_state_delta(&*service, &*hooks, caller, request).await
                }
            }
        })
        .serve_checked::<
            PlanSchemaMigration,
            _,
            _,
        >({
            let (service, hooks) = (service.clone(), hooks.clone());
            move |
                caller: strata_runtime::Caller,
                request: crate::contracts::PlanSchemaMigrationRequest|
            {
                let (service, hooks) = (service.clone(), hooks.clone());
                async move {
                    serve_plan_schema_migration(&*service, &*hooks, caller, request)
                        .await
                }
            }
        })
        .serve_checked::<
            DefineToken,
            _,
            _,
        >({
            let (service, hooks) = (service.clone(), hooks.clone());
            move |
                caller: strata_runtime::Caller,
                request: crate::contracts::DefineTokenRequest|
            {
                let (service, hooks) = (service.clone(), hooks.clone());
                async move {
                    serve_define_token(&*service, &*hooks, caller, request).await
                }
            }
        })
        .serve_checked::<
            RemoveToken,
            _,
            _,
        >({
            let (service, hooks) = (service.clone(), hooks.clone());
            move |
                caller: strata_runtime::Caller,
                request: crate::contracts::RemoveTokenRequest|
            {
                let (service, hooks) = (service.clone(), hooks.clone());
                async move {
                    serve_remove_token(&*service, &*hooks, caller, request).await
                }
            }
        })
        .serve_checked::<
            EvaluateToken,
            _,
            _,
        >({
            let (service, hooks) = (service.clone(), hooks.clone());
            move |
                caller: strata_runtime::Caller,
                request: crate::contracts::EvaluateTokenRequest|
            {
                let (service, hooks) = (service.clone(), hooks.clone());
                async move {
                    serve_evaluate_token(&*service, &*hooks, caller, request).await
                }
            }
        })
        .serve_checked::<
            HashBytes,
            _,
            _,
        >({
            let (service, hooks) = (service.clone(), hooks.clone());
            move |
                caller: strata_runtime::Caller,
                request: crate::contracts::HashBytesRequest|
            {
                let (service, hooks) = (service.clone(), hooks.clone());
                async move {
                    serve_hash_bytes(&*service, &*hooks, caller, request).await
                }
            }
        })
}

