/// Adds a route for every contract component `sqlite-adapter` implements to `routes`, each answered by `service` after the checks the specification states for it.
pub fn sqlite_adapter_routes<A, S, H>(
    routes: strata_runtime::Routes<A>,
    service: std::sync::Arc<S>,
    hooks: std::sync::Arc<H>,
) -> strata_runtime::Routes<A>
where
    A: strata_runtime::Authorizer,
    S: crate::contracts::SqliteAdapter + Send + Sync + 'static,
    H: SqliteAdapterHooks,
{
    routes.serve_checked::<OpenSqliteStore, _, _>({
        let (service, hooks) = (service.clone(), hooks.clone());
        move |caller: strata_runtime::Caller, request: crate::contracts::OpenSqliteStoreRequest| {
            let (service, hooks) = (service.clone(), hooks.clone());
            async move { serve_open_sqlite_store(&*service, &*hooks, caller, request).await }
        }
    })
}

