/// What the routes of component `web-application` (Web application) need from the deployment beyond the implementation of its contracts.
pub trait WebApplicationHooks: Send + Sync + 'static {}

/// Component `web-application` needs no hooks.
impl WebApplicationHooks for () {}

/// Answers one call of contract `show-sign-in-page`.
async fn serve_show_sign_in_page<
    S: crate::contracts::WebApplication + Sync,
    H: WebApplicationHooks,
>(
    service: &S,
    _hooks: &H,
    _caller: strata_runtime::Caller,
    request: crate::contracts::ShowSignInPageRequest,
) -> Result<
    crate::contracts::ShowSignInPageResponse,
    strata_runtime::Failure<crate::contracts::ShowSignInPageError>,
> {
    service
        .show_sign_in_page(request)
        .await
        .map_err(|error| strata_runtime::Failure::Contract { error })
}

