/// Adds a route for every contract component `web-application` implements to `routes`, each answered by `service` after the checks the specification states for it.
pub fn web_application_routes<A, S, H>(
    routes: strata_runtime::Routes<A>,
    service: std::sync::Arc<S>,
    hooks: std::sync::Arc<H>,
) -> strata_runtime::Routes<A>
where
    A: strata_runtime::Authorizer,
    S: crate::contracts::WebApplication + Send + Sync + 'static,
    H: WebApplicationHooks,
{
    routes
        .serve_checked::<
            ShowSignInPage,
            _,
            _,
        >({
            let (service, hooks) = (service.clone(), hooks.clone());
            move |
                caller: strata_runtime::Caller,
                request: crate::contracts::ShowSignInPageRequest|
            {
                let (service, hooks) = (service.clone(), hooks.clone());
                async move {
                    serve_show_sign_in_page(&*service, &*hooks, caller, request).await
                }
            }
        })
        .serve_checked::<
            ShowAuthoringView,
            _,
            _,
        >({
            let (service, hooks) = (service.clone(), hooks.clone());
            move |
                caller: strata_runtime::Caller,
                request: crate::contracts::ShowAuthoringViewRequest|
            {
                let (service, hooks) = (service.clone(), hooks.clone());
                async move {
                    serve_show_authoring_view(&*service, &*hooks, caller, request).await
                }
            }
        })
        .serve_checked::<
            SaveDraft,
            _,
            _,
        >({
            let (service, hooks) = (service.clone(), hooks.clone());
            move |
                caller: strata_runtime::Caller,
                request: crate::contracts::SaveDraftRequest|
            {
                let (service, hooks) = (service.clone(), hooks.clone());
                async move {
                    serve_save_draft(&*service, &*hooks, caller, request).await
                }
            }
        })
        .serve_checked::<
            ShowReviewDiff,
            _,
            _,
        >({
            let (service, hooks) = (service.clone(), hooks.clone());
            move |
                caller: strata_runtime::Caller,
                request: crate::contracts::ShowReviewDiffRequest|
            {
                let (service, hooks) = (service.clone(), hooks.clone());
                async move {
                    serve_show_review_diff(&*service, &*hooks, caller, request).await
                }
            }
        })
        .serve_checked::<
            PreviewTokens,
            _,
            _,
        >({
            let (service, hooks) = (service.clone(), hooks.clone());
            move |
                caller: strata_runtime::Caller,
                request: crate::contracts::PreviewTokensRequest|
            {
                let (service, hooks) = (service.clone(), hooks.clone());
                async move {
                    serve_preview_tokens(&*service, &*hooks, caller, request).await
                }
            }
        })
        .serve_checked::<
            ShowStatus,
            _,
            _,
        >({
            let (service, hooks) = (service.clone(), hooks.clone());
            move |
                caller: strata_runtime::Caller,
                request: crate::contracts::ShowStatusRequest|
            {
                let (service, hooks) = (service.clone(), hooks.clone());
                async move {
                    serve_show_status(&*service, &*hooks, caller, request).await
                }
            }
        })
        .serve_checked::<
            ShowChangelog,
            _,
            _,
        >({
            let (service, hooks) = (service.clone(), hooks.clone());
            move |
                caller: strata_runtime::Caller,
                request: crate::contracts::ShowChangelogRequest|
            {
                let (service, hooks) = (service.clone(), hooks.clone());
                async move {
                    serve_show_changelog(&*service, &*hooks, caller, request).await
                }
            }
        })
        .serve_checked::<
            ShowServiceObjectives,
            _,
            _,
        >({
            let (service, hooks) = (service.clone(), hooks.clone());
            move |
                caller: strata_runtime::Caller,
                request: crate::contracts::ShowServiceObjectivesRequest|
            {
                let (service, hooks) = (service.clone(), hooks.clone());
                async move {
                    serve_show_service_objectives(&*service, &*hooks, caller, request)
                        .await
                }
            }
        })
        .serve_checked::<
            RenderPage,
            _,
            _,
        >({
            let (service, hooks) = (service.clone(), hooks.clone());
            move |
                caller: strata_runtime::Caller,
                request: crate::contracts::RenderPageRequest|
            {
                let (service, hooks) = (service.clone(), hooks.clone());
                async move {
                    serve_render_page(&*service, &*hooks, caller, request).await
                }
            }
        })
}

