/// Adds a route for every contract component `simulator` implements to `routes`, each answered by `service` after the checks the specification states for it.
pub fn simulator_routes<A, S, H>(
    routes: strata_runtime::Routes<A>,
    service: std::sync::Arc<S>,
    hooks: std::sync::Arc<H>,
) -> strata_runtime::Routes<A>
where
    A: strata_runtime::Authorizer,
    S: crate::contracts::Simulator + Send + Sync + 'static,
    H: SimulatorHooks,
{
    routes
        .serve_checked::<RunScenario, _, _>({
            let (service, hooks) = (service.clone(), hooks.clone());
            move |caller: strata_runtime::Caller, request: crate::contracts::RunScenarioRequest| {
                let (service, hooks) = (service.clone(), hooks.clone());
                async move { serve_run_scenario(&*service, &*hooks, caller, request).await }
            }
        })
        .serve_checked::<ProjectChange, _, _>({
            let (service, hooks) = (service.clone(), hooks.clone());
            move |caller: strata_runtime::Caller,
                  request: crate::contracts::ProjectChangeRequest| {
                let (service, hooks) = (service.clone(), hooks.clone());
                async move { serve_project_change(&*service, &*hooks, caller, request).await }
            }
        })
        .serve_checked::<ReplayJournal, _, _>({
            let (service, hooks) = (service.clone(), hooks.clone());
            move |caller: strata_runtime::Caller,
                  request: crate::contracts::ReplayJournalRequest| {
                let (service, hooks) = (service.clone(), hooks.clone());
                async move { serve_replay_journal(&*service, &*hooks, caller, request).await }
            }
        })
}

